CREATE TYPE "OrganizationRole" AS ENUM ('OWNER','ADMIN','PROJECT_MANAGER','PLANNER','RESOURCE_MANAGER','CONTRIBUTOR','VIEWER');
CREATE TABLE "users" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"password_hash" TEXT NOT NULL,"first_name" TEXT NOT NULL,"last_name" TEXT NOT NULL,"email_verified_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,"PRIMARY KEY"("id"));
CREATE UNIQUE INDEX "users_email_key" ON "users"("email");
CREATE TABLE "memberships" ("id" TEXT NOT NULL,"organization_id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"role" "OrganizationRole" NOT NULL DEFAULT 'VIEWER',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("id"));
CREATE UNIQUE INDEX "memberships_organization_id_user_id_key" ON "memberships"("organization_id","user_id");
CREATE INDEX "memberships_user_id_idx" ON "memberships"("user_id");
CREATE TABLE "sessions" ("id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"token_hash" TEXT NOT NULL,"expires_at" TIMESTAMP(3) NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"last_seen_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("id"));
CREATE UNIQUE INDEX "sessions_token_hash_key" ON "sessions"("token_hash");
CREATE INDEX "sessions_user_id_idx" ON "sessions"("user_id"); CREATE INDEX "sessions_expires_at_idx" ON "sessions"("expires_at");
CREATE TABLE "invitations" ("id" TEXT NOT NULL,"organization_id" TEXT NOT NULL,"email" TEXT NOT NULL,"role" "OrganizationRole" NOT NULL DEFAULT 'CONTRIBUTOR',"token_hash" TEXT NOT NULL,"expires_at" TIMESTAMP(3) NOT NULL,"accepted_at" TIMESTAMP(3),"invited_by_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("id"));
CREATE UNIQUE INDEX "invitations_token_hash_key" ON "invitations"("token_hash"); CREATE INDEX "invitations_organization_id_email_idx" ON "invitations"("organization_id","email");
CREATE TABLE "audit_logs" ("id" TEXT NOT NULL,"organization_id" TEXT NOT NULL,"user_id" TEXT,"action" TEXT NOT NULL,"resource_type" TEXT,"resource_id" TEXT,"ip_address" TEXT,"user_agent" TEXT,"metadata" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("id"));
CREATE INDEX "audit_logs_organization_id_created_at_idx" ON "audit_logs"("organization_id","created_at");
ALTER TABLE "memberships" ADD CONSTRAINT "memberships_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "memberships" ADD CONSTRAINT "memberships_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "invitations" ADD CONSTRAINT "invitations_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "invitations" ADD CONSTRAINT "invitations_invited_by_id_fkey" FOREIGN KEY ("invited_by_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
